/** Labels that are the same product written another way. */
const ALIASES: Record<string, string> = {
  Tailwind: "Tailwind CSS",
};

export function BrandIcon({
  name,
  uid = "",
  className,
}: {
  name: string;
  /** Distinguishes the ids of two copies of the same mark on one page. */
  uid?: string;
  className?: string;
}) {
  const mark = MARKS[name] ?? MARKS[ALIASES[name]];

  if (!mark) {
    return (
      <span
        aria-hidden
        className={cn("inline-flex size-3.5 shrink-0 items-center justify-center", className)}
      >
        <span className="size-1 rounded-full bg-current opacity-40" />
      </span>
    );
  }

  return (
    <svg aria-hidden viewBox={mark.vb} fill="none" className={cn("size-3.5 shrink-0", className)}>
      {typeof mark.el === "function" ? mark.el(uid) : mark.el}
    </svg>
  );
}
